begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000009251','zona-a@example.test'),('00000000-0000-0000-0000-000000009252','zona-b@example.test');
insert into emprendimientos(id,nombre,slug) overriding system value values(-99251,'Zonas QA','zonas-qa');
insert into configuracion_entregas(emprendimiento_id,direccion_origen,latitud,longitud,franjas,modalidad,zonas) values(-99251,'Origen 123',0,0,'[]','zonas','[{"nombre":"Centro","sur":0,"norte":1,"oeste":0,"este":1,"tarifa_centavos":15000},{"nombre":"Este","sur":0,"norte":1,"oeste":1,"este":2,"tarifa_centavos":25000}]');
select ok(private.zonas_validas('[{"nombre":"A","sur":0,"norte":1,"oeste":0,"este":1,"tarifa_centavos":0}]'),'Tarifa gratuita válida');
select ok(not private.zonas_validas('[{"nombre":"A","sur":0,"norte":1,"oeste":0,"este":1,"tarifa_centavos":0},{"nombre":"B","sur":0,"norte":1,"oeste":0,"este":1,"tarifa_centavos":1}]'),'Rechaza superposición');
select ok(not private.zonas_validas('[{"nombre":"A","sur":0,"norte":0,"oeste":0,"este":1,"tarifa_centavos":0}]'),'Rechaza área vacía');
select ok(not private.zonas_validas('[{"nombre":"A","sur":0,"norte":1,"oeste":0,"tarifa_centavos":0}]'),'Rechaza límites ausentes');
select is(cotizar_entrega(-99251,.5,.5)->>'costo_centavos','15000','Tarifa de zona');
select is(cotizar_entrega(-99251,.5,1)->>'franja','Este','Borde compartido asigna una sola zona');
select throws_ok('select cotizar_entrega(-99251,1,1)','22023',null,'Fuera de cobertura');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000009251","role":"authenticated"}',true);
select lives_ok($q$select guardar_direccion_cliente('{"nombre":"Casa","direccion":"Calle 123","latitud":0.5,"longitud":0.5,"predeterminada":true}')$q$,'Cliente guarda ubicación');
select lives_ok($q$select guardar_direccion_cliente('{"nombre":"Trabajo","direccion":"Otra calle 123","latitud":0.5,"longitud":1.5,"predeterminada":true}')$q$,'Cambia predeterminada atómicamente');
select is((select count(*) from direcciones_cliente),2::bigint,'Ve sus direcciones');
select is((select count(*) from direcciones_cliente where predeterminada),1::bigint,'Una sola predeterminada');
select throws_ok($q$insert into direcciones_cliente(usuario_id,nombre,direccion,latitud,longitud) values('00000000-0000-0000-0000-000000009252','Ajena','Otra calle 123',0,0)$q$,'42501',null,'No puede guardar para otro cliente');
select throws_ok($q$update direcciones_cliente set usuario_id='00000000-0000-0000-0000-000000009252'$q$,'42501',null,'No transfiere propiedad');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000009252","role":"authenticated"}',true);
select is((select count(*) from direcciones_cliente),0::bigint,'Otro cliente no ve direcciones');
with borradas as(delete from direcciones_cliente returning id) select is(count(*),0::bigint,'Otro cliente no elimina direcciones') from borradas;
with editadas as(update configuracion_entregas set zonas='[]' where emprendimiento_id=-99251 returning emprendimiento_id) select is(count(*),0::bigint,'Cliente no configura tarifas') from editadas;
set local role anon;
select throws_ok('select * from direcciones_cliente','42501',null,'Anónimo no ve direcciones');
set local role postgres;
update configuracion_entregas set modalidad='radio',franjas='[{"hasta_m":1000,"tarifa_centavos":900}]' where emprendimiento_id=-99251;
select is(cotizar_entrega(-99251,0,0)->>'costo_centavos','900','Conserva modalidad por radio');
select * from finish();
rollback;
